policies.inbound:
{{skill-agent-api-audience}}


https://sts.windows.net/{{tenant-id}}/
https://login.microsoftonline.com/{{tenant-id}}/v2.0



{{webapp-principal-id}}





<set-variable name="userOid" value="@{
var b = context.Request.Body?.As(preserveContent: true);
var oid = (string)b?["user"]?["oid"];
return (oid != null && System.Text.RegularExpressions.Regex.IsMatch(oid, "^[0-9a-fA-F-]{8,64}$")) ? oid.ToLowerInvariant() : "anonymous";
}" />




@("{{token-ledger-table-url}}/tokenusage(PartitionKey='" + "user-" + (string)context.Variables["userOid"] + "',RowKey='" + (string)context.Variables["day"] + "')")
GET
application/json;odata=nometadata
2019-02-02
@(DateTime.UtcNow.ToString("R"))



@("{{token-ledger-table-url}}/tokenusage(PartitionKey='" + "app" + "',RowKey='" + (string)context.Variables["month"] + "')")
GET
application/json;odata=nometadata
2019-02-02
@(DateTime.UtcNow.ToString("R"))


<set-variable name="userUsed" value="@{
var r = context.Variables.GetValueOrDefault("userRow");
if (r == null || r.StatusCode != 200) { return 0L; }
return (long?)r.Body.As(preserveContent: true)["tokens"] ?? 0L;
}" />
<set-variable name="appUsed" value="@{
var r = context.Variables.GetValueOrDefault("appRow");
if (r == null || r.StatusCode != 200) { return 0L; }
return (long?)r.Body.As(preserveContent: true)["tokens"] ?? 0L;
}" />
<set-variable name="ledgerOk" value="@{
var a = context.Variables.GetValueOrDefault("userRow");
var b = context.Variables.GetValueOrDefault("appRow");
return a != null && b != null && (a.StatusCode == 200 || a.StatusCode == 404) && (b.StatusCode == 200 || b.StatusCode == 404);
}" />



{{token-ledger-table-url}}/tokenledger
POST
application/json;odata=nometadata
2019-02-02
@(DateTime.UtcNow.ToString("R"))
application/json
return-no-content
@{
var u = new JObject(new JProperty("in", 0L), new JProperty("out", 0L), new JProperty("total", 0L), new JProperty("cost", 0.0), new JProperty("calls", 0L), new JProperty("skill", ""));
return new JObject(
new JProperty("PartitionKey", "user-" + (string)context.Variables["userOid"]),
new JProperty("RowKey", DateTime.UtcNow.ToString("yyyyMMddHHmmssfff") + "-" + context.RequestId.ToString("N")),
new JProperty("day", (string)context.Variables["day"]),
new JProperty("status", "rejected_user_daily_limit"),
new JProperty("skill", (string)u["skill"]),
new JProperty("session_id", context.Variables.GetValueOrDefault("sessionOut", (string)context.Variables["sessionIn"])),
new JProperty("model_calls", (long)u["calls"]),
new JProperty("input_tokens", (long)u["in"]),
new JProperty("output_tokens", (long)u["out"]),
new JProperty("total_tokens", (long)u["total"]),
new JProperty("cost_usd", (double)u["cost"]),
new JProperty("user_tokens_today", context.Variables.GetValueOrDefault("uNew", (long)context.Variables["userUsed"])),
new JProperty("app_tokens_month", context.Variables.GetValueOrDefault("aNew", (long)context.Variables["appUsed"])),
new JProperty("apim_request_id", context.RequestId.ToString())
).ToString();
}




application/json
@(((int)(DateTime.UtcNow.Date.AddDays(1) - DateTime.UtcNow).TotalSeconds).ToString())
@(new JObject(new JProperty("error", "rejected_user_daily_limit"), new JProperty("message", "You have used your daily token allowance. It resets at 00:00 UTC."), new JProperty("limit", long.Parse("{{token-limit-user-daily}}")), new JProperty("used", (long)context.Variables["userUsed"])).ToString())




