application/json
@(((int)(new DateTime(DateTime.UtcNow.Year, DateTime.UtcNow.Month, 1).AddMonths(1) - DateTime.UtcNow).TotalSeconds).ToString())
@(new JObject(new JProperty("error", "rejected_app_monthly_limit"), new JProperty("message", "The app has used its monthly token budget. It resets on the 1st (UTC)."), new JProperty("limit", long.Parse("{{token-limit-app-monthly}}")), new JProperty("used", (long)context.Variables["appUsed"])).ToString())











